<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$termId=filter_var($_POST['term_id']??null,FILTER_VALIDATE_INT);$classId=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$subjectId=filter_var($_POST['subject_id']??null,FILTER_VALIDATE_INT);$title=trim((string)($_POST['title']??''));$type=(string)($_POST['assessment_type']??'');$max=(string)($_POST['max_mark']??'');$date=trim((string)($_POST['held_on']??''));
$types=['Test','Assignment','Practical','Coursework','Examination'];
if(!$termId||!$classId||!$subjectId||$title===''||strlen($title)>120||!in_array($type,$types,true)||!is_numeric($max)||(float)$max<=0||(float)$max>10000){$_SESSION['error']='Check the assessment details and maximum mark.';header('Location: ../?page=academics&tab=assessments');exit;}
if($date!==''&&!valid_assessment_date($date)){$_SESSION['error']='Enter a valid assessment date.';header('Location: ../?page=academics&tab=assessments');exit;}
$pdo=db();$query=$pdo->prepare('SELECT t.academic_year,t.starts_on,t.ends_on,c.form_level,c.stream,c.academic_year AS class_year,cs.teacher_id,c.class_teacher_id,s.level,s.active FROM school_terms t JOIN class_groups c ON c.id=:class_id JOIN class_subjects cs ON cs.class_id=c.id AND cs.subject_id=:subject_id JOIN subjects s ON s.id=cs.subject_id WHERE t.id=:term_id');
$query->execute(['class_id'=>$classId,'subject_id'=>$subjectId,'term_id'=>$termId]);$context=$query->fetch();
if(!$context||!(int)$context['active']||(int)$context['academic_year']!==(int)$context['class_year']||($context['level']==='O-Level'&&(int)$context['form_level']>4)||($context['level']==='A-Level'&&(int)$context['form_level']<5)||($date!==''&&($date<$context['starts_on']||$date>$context['ends_on']))){$_SESSION['error']='The selected class, term, subject level and date do not match.';header('Location: ../?page=academics&tab=assessments');exit;}
if($user['role']==='Teacher'&&(int)$context['teacher_id']!==(int)$user['id']&&(int)$context['class_teacher_id']!==(int)$user['id']){http_response_code(403);exit('You are not assigned to this subject.');}
try{$stmt=$pdo->prepare('INSERT INTO assessments (term_id,subject_id,class_id,title,assessment_type,max_mark,held_on) VALUES (:term,:subject,:class,:title,:type,:max,:date)');$stmt->execute(['term'=>$termId,'subject'=>$subjectId,'class'=>$classId,'title'=>$title,'type'=>$type,'max'=>number_format((float)$max,2,'.',''),'date'=>$date?:null]);$id=(int)$pdo->lastInsertId();audit_log('assessment.created','assessments',$id,['type'=>$type,'max_mark'=>(float)$max]);$_SESSION['notice']='Assessment created. Enter marks when ready.';header('Location: ../?page=academics&tab=assessments&id='.$id);exit;}catch(Throwable $e){error_log('Assessment create failed: '.$e->getMessage());$_SESSION['error']='Could not create the assessment. Please try again.';header('Location: ../?page=academics&tab=assessments');exit;}

function valid_assessment_date(string $date): bool {if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))return false;$value=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$errors=DateTimeImmutable::getLastErrors();return $value!==false&&$value->format('Y-m-d')===$date&&($errors===false||(!$errors['warning_count']&&!$errors['error_count']));}
